// ── Builder (Android `DimenScaled` / `ScaledSp`). ───────────────────────────
/** Custom-dimension builder for the scaled strategy. */
export class DimenScaled extends DimenBuilder {
}
/** Starts a builder: `scaledDp(16).screen(UiModeType.TELEVISION, 40).sdp`. */
export const scaledDp = (value: number): DimenScaled => new DimenScaled(B, value);
/** Text builder (same class; read `.ssp` / `.sem`). */
export const scaledSp = (value: number): DimenScaled => new DimenScaled(B, value);
